const ELEMENT_PROP_KEYS = new Set(["theme","title","inner","hold","accent","innerColor","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "Ship the story",
  inner: "with motion you own",
  hold: 32,
  accent: "#3B5BFD",
  innerColor: "#f4f7ff",
  fontFamily: "Bricolage Grotesque",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type BeamSplitElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BeamSplitBase>;

const BeamSplitInner = forwardRef<
  HTMLDivElement,
  BeamSplitElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BeamSplit>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BeamSplitBase
          {...(componentProps as unknown as ComponentProps<typeof BeamSplitBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BeamSplit = Interactive.withSchema({
  Component: BeamSplitInner,
  componentName: "<BeamSplit>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
